/** Thrown for any malformed class file, descriptor, string or bytecode. */
public final class ClassFormatException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public ClassFormatException(String message) {
        super(message);
    }
}

code.src/main/java/ae/classfile/ClassReader.j:
package ae.classfile;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Strict class-file parser (JVMS chapter 4); every defect becomes a {@link ClassFormatException}. */
public final class ClassReader {
    private static final int MIN_MAJOR = 45;
    private static final int MAX_MAJOR = 65;

    private final byte[] data;
    private int pos;

    private ClassReader(byte[] data) {
        this.data = data;
    }

    public static ClassFile parse(byte[] image) {
        return new ClassReader(image).read();
    }

    /** Decodes and validates a Code attribute body. */
    static CodeAttr parseCode(ConstantPool pool, byte[] body) {
        ClassReader r = new ClassReader(body);
        int maxStack = r.u2();
        int maxLocals = r.u2();
        long codeLength = r.u4();
        if (codeLength < 1 || codeLength > 65535) {
            throw new ClassFormatException("bad code length " + codeLength);
        }
        byte[] code = r.bytes((int) codeLength);
        int n = r.u2();
        List<ExceptionEntry> handlers = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int start = r.u2();
            int end = r.u2();
            int handler = r.u2();
            int type = r.u2();
            if (start >= end || end > code.length || handler >= code.length) {
                throw new ClassFormatException("bad exception table row " + i + ": " + start + ".." + end + " -> " + handler);
            }
            if (type != 0) {
                pool.className(type);
            }
            handlers.add(new ExceptionEntry(start, end, handler, type));
        }
        List<Attribute> attrs = r.attributes(pool);
        if (r.pos != body.length) {
            throw new ClassFormatException("Code attribute length does not match its content");
        }
        return new CodeAttr(maxStack, maxLocals, code, List.copyOf(handlers), List.copyOf(attrs));
    }

    private ClassFile read() {
        if (u4() != 0xCAFEBABEL) {
            throw new ClassFormatException("bad magic number");
        }
        int minor = u2();
        int major = u2();
        if (major < MIN_MAJOR || major > MAX_MAJOR) {
            throw new ClassFormatException("unsupported version " + major + "." + minor);
        }
        ConstantPool pool = readPool();
        int access = u2();
        int thisIndex = u2();
        pool.className(thisIndex);
        int superIndex = u2();
        if (superIndex == 0) {
            if (!pool.className(thisIndex).equals("java/lang/Object") && (access & ClassFile.ACC_MODULE) == 0) {
                throw new ClassFormatException("missing superclass for " + pool.className(thisIndex));
            }
        } else {
            pool.className(superIndex);
        }
        int ifaceCount = u2();
        List<Integer> ifaces = new ArrayList<>();
        for (int i = 0; i < ifaceCount; i++) {
            int idx = u2();
            pool.className(idx);
            ifaces.add(idx);
        }
        List<Member> fields = members(pool, false);
        List<Member> methods = members(pool, true);
        List<Attribute> attrs = attributes(pool);
        if (pos != data.length) {
            throw new ClassFormatException("trailing bytes after class file (" + (data.length - pos) + ")");
        }
        return new ClassFile(minor, major, pool, access, thisIndex, superIndex, List.copyOf(ifaces),
            List.copyOf(fields), List.copyOf(methods), List.copyOf(attrs));
    }

    private ConstantPool readPool() {
        int count = u2();
        if (count == 0) {
            throw new ClassFormatException("constant pool count is zero");
        }
        Constant[] e = new Constant[count];
        for (int i = 1; i < count; i++) {
            int tag = u1();
            switch (tag) {
                case 1 -> {
                    int len = u2();
                    e[i] = new Constant.Utf8(ModifiedUtf8.decode(data, need(len), len));
                    pos += len;
                }
                case 3 -> e[i] = new Constant.IntegerC((int) u4());
                case 4 -> e[i] = new Constant.FloatC((int) u4());
                case 5, 6 -> {
                    if (i + 1 >= count) {
                        throw new ClassFormatException("long/double constant at #" + i + " overruns the pool");
                    }
                    long v = (u4() << 32) | u4();
                    e[i] = tag == 5 ? new Constant.LongC(v) : new Constant.DoubleC(v);
                    i++;
                }
                case 7 -> e[i] = new Constant.ClassRef(u2());
                case 8 -> e[i] = new Constant.StringRef(u2());
                case 9 -> e[i] = new Constant.FieldRef(u2(), u2());
                case 10 -> e[i] = new Constant.MethodRef(u2(), u2());
                case 11 -> e[i] = new Constant.InterfaceMethodRef(u2(), u2());
                case 12 -> e[i] = new Constant.NameAndType(u2(), u2());
                case 15 -> e[i] = new Constant.MethodHandle(u1(), u2());
                case 16 -> e[i] = new Constant.MethodType(u2());
                case 17 -> e[i] = new Constant.Dynamic(u2(), u2());
                case 18 -> e[i] = new Constant.InvokeDynamic(u2(), u2());
                case 19 -> e[i] = new Constant.ModuleRef(u2());
                case 20 -> e[i] = new Constant.PackageRef(u2());
                default -> throw new ClassFormatException("unknown constant tag " + tag + " at #" + i);
            }
        }
        ConstantPool pool = new ConstantPool(e);
        for (int i = 1; i < count; i++) {
            if (e[i] != null) {
                validate(pool, e[i]);
            }
        }
        return pool;
    }

    private static void validate(ConstantPool pool, Constant c) {
        switch (c) {
            case Constant.ClassRef r -> pool.utf8(r.nameIndex());
            case Constant.StringRef r -> pool.utf8(r.utf8Index());
            case Constant.MethodType r -> pool.utf8(r.descIndex());
            case Constant.ModuleRef r -> pool.utf8(r.nameIndex());
            case Constant.PackageRef r -> pool.utf8(r.nameIndex());
            case Constant.NameAndType r -> {
                pool.utf8(r.nameIndex());
                pool.utf8(r.descIndex());
            }
            case Constant.FieldRef r -> owner(pool, r.classIndex(), r.natIndex());
            case Constant.MethodRef r -> owner(pool, r.classIndex(), r.natIndex());
            case Constant.InterfaceMethodRef r -> owner(pool, r.classIndex(), r.natIndex());
            case Constant.Dynamic r -> nameAndType(pool, r.natIndex());
            case Constant.InvokeDynamic r -> nameAndType(pool, r.natIndex());
            case Constant.MethodHandle h -> {
                if (h.kind() < 1 || h.kind() > 9) {
                    throw new ClassFormatException("bad method handle kind " + h.kind());
                }
                Constant target = pool.get(h.refIndex());
                boolean ok = switch (h.kind()) {
                    case 1, 2, 3, 4 -> target instanceof Constant.FieldRef;
                    case 9 -> target instanceof Constant.InterfaceMethodRef;
                    default -> target instanceof Constant.MethodRef || target instanceof Constant.InterfaceMethodRef;
                };
                if (!ok) {
                    throw pool.wrong(h.refIndex(), "a reference matching handle kind " + h.kind());
                }
            }
            case Constant.Utf8 u -> { }
            case Constant.IntegerC u -> { }
            case Constant.FloatC u -> { }
            case Constant.LongC u -> { }
            case Constant.DoubleC u -> { }
        }
    }

    private static void owner(ConstantPool pool, int classIndex, int natIndex) {
        pool.className(classIndex);
        nameAndType(pool, natIndex);
    }

    private static void nameAndType(ConstantPool pool, int natIndex) {
        if (!(pool.get(natIndex) instanceof Constant.NameAndType)) {
            throw pool.wrong(natIndex, "NameAndType");
        }
    }

    private List<Member> members(ConstantPool pool, boolean methods) {
        int n = u2();
        List<Member> out = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int access = u2();
            int nameIdx = u2();
            int descIdx = u2();
            String name = pool.utf8(nameIdx);
            String desc = pool.utf8(descIdx);
            if (methods) {
                checkMethodName(name);
                Descriptor.parseMethod(desc);
            } else {
                checkUnqualified(name);
                Descriptor.parseField(desc);
            }
            if (!seen.add(name + ":" + desc)) {
                throw new ClassFormatException("duplicate member " + name + desc);
            }
            List<Attribute> attrs = attributes(pool);
            if (methods) {
                checkCodePresence(pool, access, name, attrs);
            }
            out.add(new Member(access, nameIdx, descIdx, name, desc, List.copyOf(attrs)));
        }
        return out;
    }

    private static void checkCodePresence(ConstantPool pool, int access, String name, List<Attribute> attrs) {
        int codes = 0;
        Attribute code = null;
        for (Attribute a : attrs) {
            if (a.name().equals("Code")) {
                codes++;
                code = a;
            }
        }
        boolean bodyless = (access & (ClassFile.ACC_ABSTRACT | ClassFile.ACC_NATIVE)) != 0;
        if (bodyless && codes > 0) {
            throw new ClassFormatException("method " + name + " must not have Code");
        }
        if (!bodyless && codes == 0) {
            throw new ClassFormatException("method " + name + " is missing Code");
        }
        if (codes > 1) {
            throw new ClassFormatException("method " + name + " has multiple Code attributes");
        }
        if (code != null) {
            parseCode(pool, code.data());
        }
    }

    private static void checkUnqualified(String name) {
        if (name.isEmpty() || name.indexOf('.') >= 0 || name.indexOf(';') >= 0 || name.indexOf('[') >= 0
            || name.indexOf('/') >= 0) {
            throw new ClassFormatException("bad name '" + name + "'");
        }
    }

    private static void checkMethodName(String name) {
        checkUnqualified(name);
        boolean special = name.equals("<init>") || name.equals("<clinit>");
        if (!special && (name.indexOf('<') >= 0 || name.indexOf('>') >= 0)) {
            throw new ClassFormatException("bad name '" + name + "'");
        }
    }

    private List<Attribute> attributes(ConstantPool pool) {
        int n = u2();
        List<Attribute> out = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int nameIdx = u2();
            String name = pool.utf8(nameIdx);
            long len = u4();
            if (len > data.length - pos) {
                throw new ClassFormatException("truncated attribute " + name);
            }
            out.add(new Attribute(nameIdx, name, bytes((int) len)));
        }
        return out;
    }

    // ---- cursor ------------------------------------------------------------

    /** Checks that {@code n} more bytes exist and returns the current position. */
    private int need(int n) {
        if (n < 0 || n > data.length - pos) {
            throw new ClassFormatException("truncated class file at offset " + pos);
        }
        return pos;
    }

    private int u1() {
        need(1);
        return data[pos++] & 0xFF;
    }

    private int u2() {
        need(2);
        int v = ((data[pos] & 0xFF) << 8) | (data[pos + 1] & 0xFF);
        pos += 2;
        return v;
    }

    private long u4() {
        need(4);
        long v = ((long) (data[pos] & 0xFF) << 24) | ((data[pos + 1] & 0xFF) << 16)
            | ((data[pos + 2] & 0xFF) << 8) | (data[pos + 3] & 0xFF);
        pos += 4;
        return v;
    }

    private byte[] bytes(int n) {
        need(n);
        byte[] r = java.util.Arrays.copyOfRange(data, pos, pos + n);
        pos += n;
        return r;
    }
}

code.src/main/java/ae/classfile/ClassWriter.j:
package ae.classfile;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;

/** Serialises a {@link ClassFile}; the exact inverse of {@link ClassReader#parse}. */
public final class ClassWriter {
    private ClassWriter() {
    }

    public static byte[] toBytes(ClassFile cf) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        DataOutputStream o = new DataOutputStream(bos);
        try {
            o.writeInt(0xCAFEBABE);
            o.writeShort(cf.minor());
            o.writeShort(cf.major());
            Constant[] pool = cf.pool().raw();
            o.writeShort(pool.length);
            for (Constant c : pool) {
                if (c != null) {
                    writeConstant(o, c);
                }
            }
            o.writeShort(cf.access());
            o.writeShort(cf.thisIndex());
            o.writeShort(cf.superIndex());
            o.writeShort(cf.interfaceIndexes().size());
            for (int i : cf.interfaceIndexes()) {
                o.writeShort(i);
            }
            members(o, cf.fields());
            members(o, cf.methods());
            attributes(o, cf.attributes());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return bos.toByteArray();
    }

    private static void members(DataOutputStream o, java.util.List<Member> ms) throws IOException {
        o.writeShort(ms.size());
        for (Member m : ms) {
            o.writeShort(m.access());
            o.writeShort(m.nameIndex());
            o.writeShort(m.descriptorIndex());
            attributes(o, m.attributes());
        }
    }

    private static void attributes(DataOutputStream o, java.util.List<Attribute> as) throws IOException {
        o.writeShort(as.size());
        for (Attribute a : as) {
            o.writeShort(a.nameIndex());
            o.writeInt(a.data().length);
            o.write(a.data());
        }
    }

    private static void writeConstant(DataOutputStream o, Constant c) throws IOException {
        switch (c) {
            case Constant.Utf8 u -> {
                byte[] b = ModifiedUtf8.encode(u.value());
                o.writeByte(1);
                o.writeShort(b.length);
                o.write(b);
            }
            case Constant.IntegerC v -> {
                o.writeByte(3);
                o.writeInt(v.value());
            }
            case Constant.FloatC v -> {
                o.writeByte(4);
                o.writeInt(v.bits());
            }
            case Constant.LongC v -> {
                o.writeByte(5);
                o.writeLong(v.value());
            }
            case Constant.DoubleC v -> {
                o.writeByte(6);
                o.writeLong(v.bits());
            }
            case Constant.ClassRef v -> two(o, 7, v.nameIndex());
            case Constant.StringRef v -> two(o, 8, v.utf8Index());
            case Constant.FieldRef v -> three(o, 9, v.classIndex(), v.natIndex());
            case Constant.MethodRef v -> three(o, 10, v.classIndex(), v.natIndex());
            case Constant.InterfaceMethodRef v -> three(o, 11, v.classIndex(), v.natIndex());
            case Constant.NameAndType v -> three(o, 12, v.nameIndex(), v.descIndex());
            case Constant.MethodHandle v -> {
                o.writeByte(15);
                o.writeByte(v.kind());
                o.writeShort(v.refIndex());
            }
            case Constant.MethodType v -> two(o, 16, v.descIndex());
            case Constant.Dynamic v -> three(o, 17, v.bootstrapIndex(), v.natIndex());
            case Constant.InvokeDynamic v -> three(o, 18, v.bootstrapIndex(), v.natIndex());
            case Constant.ModuleRef v -> two(o, 19, v.nameIndex());
            case Constant.PackageRef v -> two(o, 20, v.nameIndex());
        }
    }

    private static void two(DataOutputStream o, int tag, int a) throws IOException {
        o.writeByte(tag);
        o.writeShort(a);
    }

    private static void three(DataOutputStream o, int tag, int a, int b) throws IOException {
        o.writeByte(tag);
        o.writeShort(a);
        o.writeShort(b);
    }
}

package ae.classfile;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Abstract interpretation of a method body that tracks operand-stack depth in slots.
 *
 * <p>Fixed effects come from {@link Opcodes#effect}; field, invoke, ldc and multianewarray effects
 * come from the constant pool. Depths must agree wherever control flow merges, exception handlers
 * start at depth 1, and unreachable code is ignored. jsr/ret are not supported.
 */
public final class CodeAnalyzer {
    private final ClassFile cf;
    private final ConstantPool pool;
    private final List<Instruction> ins;
    private final Map<Integer, Integer> indexOf = new HashMap<>();
    private final int[] depth;
    private final Deque<Integer> work = new ArrayDeque<>();
    private int maxStack;
    private int locals;

    private CodeAnalyzer(ClassFile cf, List<Instruction> ins, int initialLocals) {
        this.cf = cf;
        this.pool = cf.pool();
        this.ins = ins;
        this.depth = new int[ins.size()];
        Arrays.fill(depth, -1);
        this.locals = initialLocals;
        for (int i = 0; i < ins.size(); i++) {
            indexOf.put(ins.get(i).offset(), i);
        }
    }

    public static Analysis analyze(ClassFile cf, Member method) {
        CodeAttr code = cf.code(method).orElseThrow(() -> new ClassFormatException("method " + method.name() + " has no code"));
        List<Instruction> ins = Disassembler.decode(code.code());
        Disassembler.validateTargets(ins, code.code().length);
        MethodDescriptor md = Descriptor.parseMethod(method.descriptor());
        int initial = md.argSlots() + ((method.access() & ClassFile.ACC_STATIC) == 0 ? 1 : 0);
        CodeAnalyzer a = new CodeAnalyzer(cf, ins, initial);
        return a.run(code);
    }

    private Analysis run(CodeAttr code) {
        merge(0, 0);
        drain();
        boolean changed = true;
        while (changed) {
            changed = false;
            for (ExceptionEntry h : code.handlers()) {
                Integer target = indexOf.get(h.handler());
                if (target == null) {
                    throw new ClassFormatException("exception handler " + h.handler() + " is not an instruction start");
                }
                if (coversReachable(h, code.code().length) && depth[target] != 1) {
                    merge(target, 1);
                    drain();
                    changed = true;
                }
            }
        }
        int reachable = 0;
        for (int d : depth) {
            if (d >= 0) {
                reachable++;
            }
        }
        return new Analysis(maxStack, locals, reachable);
    }

    private boolean coversReachable(ExceptionEntry h, int codeLength) {
        if (!indexOf.containsKey(h.start()) || (h.end() != codeLength && !indexOf.containsKey(h.end()))) {
            throw new ClassFormatException("exception table range " + h.start() + ".." + h.end()
                + " does not align with instructions");
        }
        for (int i = indexOf.get(h.start()); i < ins.size() && ins.get(i).offset() < h.end(); i++) {
            if (depth[i] >= 0) {
                return true;
            }
        }
        return false;
    }

    private void merge(int index, int d) {
        if (depth[index] == -1) {
            depth[index] = d;
            maxStack = Math.max(maxStack, d);
            work.push(index);
        } else if (depth[index] != d) {
            throw new ClassFormatException("inconsistent stack depth at offset " + ins.get(index).offset()
                + ": " + depth[index] + " vs " + d);
        }
    }

    private void drain() {
        while (!work.isEmpty()) {
            step(work.pop());
        }
    }

    private void step(int index) {
        Instruction in = ins.get(index);
        int op = in.opcode();
        int before = depth[index];
        if (op == Opcodes.JSR || op == Opcodes.RET || op == Opcodes.JSR_W) {
            throw new ClassFormatException("jsr/ret are not supported (offset " + in.offset() + ")");
        }
        int pops;
        int pushes;
        int[] fixed = Opcodes.effect(op);
        if (fixed != null) {
            pops = fixed[0];
            pushes = fixed[1];
        } else {
            int[] e = poolEffect(in);
            pops = e[0];
            pushes = e[1];
        }
        trackLocals(in);
        if (before < pops) {
            throw new ClassFormatException("stack underflow at offset " + in.offset() + " (" + in.mnemonic()
                + " needs " + pops + ", has " + before + ")");
        }
        int after = before - pops + pushes;
        maxStack = Math.max(maxStack, after);
        boolean falls = true;
        switch (Opcodes.kind(op)) {
            case BRANCH -> {
                merge(indexOf.get(in.targets()[0]), after);
                falls = op != Opcodes.GOTO && op != Opcodes.GOTO_W;
            }
            case SWITCH -> {
                for (int t : in.targets()) {
                    merge(indexOf.get(t), after);
                }
                falls = false;
            }
            default -> {
                if (op >= 0xac && op <= 0xb1 || op == Opcodes.ATHROW) {
                    falls = false;
                }
            }
        }
        if (falls) {
            if (index + 1 >= ins.size()) {
                throw new ClassFormatException("code falls off the end after offset " + in.offset());
            }
            merge(index + 1, after);
        }
    }

    private void trackLocals(Instruction in) {
        int op = in.opcode();
        boolean touches = (op >= 0x15 && op <= 0x19) || (op >= 0x1a && op <= 0x2d) || (op >= 0x36 && op <= 0x3a)
            || (op >= 0x3b && op <= 0x4e) || op == Opcodes.IINC;
        if (touches) {
            locals = Math.max(locals, in.operand() + Opcodes.localSize(op));
        }
    }

    private int[] poolEffect(Instruction in) {
        int op = in.opcode();
        switch (op) {
            case Opcodes.LDC, Opcodes.LDC_W -> {
                Constant c = pool.get(in.operand());
                return new int[] {0, switch (c) {
                    case Constant.IntegerC x -> 1;
                    case Constant.FloatC x -> 1;
                    case Constant.StringRef x -> 1;
                    case Constant.ClassRef x -> 1;
                    case Constant.MethodType x -> 1;
                    case Constant.MethodHandle x -> 1;
                    case Constant.Dynamic x -> Descriptor.parseField(pool.memberRef(in.operand()).descriptor()).slots();
                    case Constant.LongC x -> throw new ClassFormatException(in.mnemonic() + " of a long constant at " + in.offset());
                    case Constant.DoubleC x -> throw new ClassFormatException(in.mnemonic() + " of a double constant at " + in.offset());
                    default -> throw new ClassFormatException("bad ldc constant at #" + in.operand() + " (offset " + in.offset() + ")");
                }};
            }
            case Opcodes.LDC2_W -> {
                Constant c = pool.get(in.operand());
                boolean ok = c instanceof Constant.LongC || c instanceof Constant.DoubleC
                    || (c instanceof Constant.Dynamic && Descriptor.parseField(pool.memberRef(in.operand()).descriptor()).slots() == 2);
                if (!ok) {
                    throw new ClassFormatException("ldc2_w needs a long or double constant at offset " + in.offset());
                }
                return new int[] {0, 2};
            }
            case Opcodes.GETSTATIC, Opcodes.PUTSTATIC, Opcodes.GETFIELD, Opcodes.PUTFIELD -> {
                if (!(pool.get(in.operand()) instanceof Constant.FieldRef)) {
                    throw pool.wrong(in.operand(), "Fieldref");
                }
                int size = Descriptor.parseField(pool.memberRef(in.operand()).descriptor()).slots();
                return switch (op) {
                    case Opcodes.GETSTATIC -> new int[] {0, size};
                    case Opcodes.PUTSTATIC -> new int[] {size, 0};
                    case Opcodes.GETFIELD -> new int[] {1, size};
                    default -> new int[] {1 + size, 0};
                };
            }
            case Opcodes.INVOKEVIRTUAL, Opcodes.INVOKESPECIAL, Opcodes.INVOKESTATIC, Opcodes.INVOKEINTERFACE,
                 Opcodes.INVOKEDYNAMIC -> {
                Constant c = pool.get(in.operand());
                boolean ok = switch (op) {
                    case Opcodes.INVOKEVIRTUAL -> c instanceof Constant.MethodRef;
                    case Opcodes.INVOKEINTERFACE -> c instanceof Constant.InterfaceMethodRef;
                    case Opcodes.INVOKEDYNAMIC -> c instanceof Constant.InvokeDynamic;
                    default -> c instanceof Constant.MethodRef || c instanceof Constant.InterfaceMethodRef;
                };
                if (!ok) {
                    throw pool.wrong(in.operand(), "a method reference suitable for " + in.mnemonic());
                }
                MethodDescriptor md = Descriptor.parseMethod(pool.memberRef(in.operand()).descriptor());
                boolean hasReceiver = op != Opcodes.INVOKESTATIC && op != Opcodes.INVOKEDYNAMIC;
                int args = md.argSlots();
                if (op == Opcodes.INVOKEINTERFACE && in.operand2() != args + 1) {
                    throw new ClassFormatException("invokeinterface count " + in.operand2() + " should be " + (args + 1)
                        + " at offset " + in.offset());
                }
                return new int[] {args + (hasReceiver ? 1 : 0), md.ret().slots()};
            }
            case Opcodes.MULTIANEWARRAY -> {
                String cls = pool.className(in.operand());
                int rank = 0;
                while (rank < cls.length() && cls.charAt(rank) == '[') {
                    rank++;
                }
                if (in.operand2() > rank) {
                    throw new ClassFormatException("multianewarray dimensions " + in.operand2() + " exceed array rank "
                        + rank + " at offset " + in.offset());
                }
                return new int[] {in.operand2(), 1};
            }
            default -> throw new ClassFormatException("no stack effect for " + in.mnemonic());
        }
    }
}

