package ae.classfile;

/** A constant-pool entry. Floating-point values keep their raw bits so NaN payloads round-trip. */
public sealed interface Constant {
    record Utf8(String value) implements Constant { }

    record IntegerC(int value) implements Constant { }

    record FloatC(int bits) implements Constant { }

    record LongC(long value) implements Constant { }

    record DoubleC(long bits) implements Constant { }

    record ClassRef(int nameIndex) implements Constant { }

    record StringRef(int utf8Index) implements Constant { }

    record FieldRef(int classIndex, int natIndex) implements Constant { }

    record MethodRef(int classIndex, int natIndex) implements Constant { }

    record InterfaceMethodRef(int classIndex, int natIndex) implements Constant { }

    record NameAndType(int nameIndex, int descIndex) implements Constant { }

    record MethodHandle(int kind, int refIndex) implements Constant { }

    record MethodType(int descIndex) implements Constant { }

    record Dynamic(int bootstrapIndex, int natIndex) implements Constant { }

    record InvokeDynamic(int bootstrapIndex, int natIndex) implements Constant { }

    record ModuleRef(int nameIndex) implements Constant { }

    record PackageRef(int nameIndex) implements Constant { }
}

package ae.classfile;

/** The 1-based constant pool; the slot after a Long or Double is not addressable. */
public final class ConstantPool {
    private final Constant[] entries;

    /** @param entries array of length {@code constant_pool_count}; index 0 and Long/Double second slots are null */
    ConstantPool(Constant[] entries) {
        this.entries = entries;
    }

    /** The value of {@code constant_pool_count} (highest index + 1). */
    public int size() {
        return entries.length;
    }

    public Constant get(int index) {
        if (index <= 0 || index >= entries.length || entries[index] == null) {
            throw new ClassFormatException("constant pool index " + index + " out of range or invalid (count "
                + entries.length + ")");
        }
        return entries[index];
    }

    public String utf8(int index) {
        if (get(index) instanceof Constant.Utf8 u) {
            return u.value();
        }
        throw wrong(index, "Utf8");
    }

    public String className(int index) {
        if (get(index) instanceof Constant.ClassRef c) {
            return utf8(c.nameIndex());
        }
        throw wrong(index, "Class");
    }

    /** Resolves Fieldref, Methodref, InterfaceMethodref (owner set) and Dynamic/InvokeDynamic (owner null). */
    public MemberRef memberRef(int index) {
        Constant c = get(index);
        int cls;
        int nat;
        switch (c) {
            case Constant.FieldRef f -> {
                cls = f.classIndex();
                nat = f.natIndex();
            }
            case Constant.MethodRef m -> {
                cls = m.classIndex();
                nat = m.natIndex();
            }
            case Constant.InterfaceMethodRef m -> {
                cls = m.classIndex();
                nat = m.natIndex();
            }
            case Constant.Dynamic d -> {
                cls = 0;
                nat = d.natIndex();
            }
            case Constant.InvokeDynamic d -> {
                cls = 0;
                nat = d.natIndex();
            }
            default -> throw wrong(index, "a member reference");
        }
        if (!(get(nat) instanceof Constant.NameAndType nt)) {
            throw wrong(nat, "NameAndType");
        }
        return new MemberRef(cls == 0 ? null : className(cls), utf8(nt.nameIndex()), utf8(nt.descIndex()));
    }

    ClassFormatException wrong(int index, String expected) {
        String found = entries[index] == null ? "nothing" : entries[index].getClass().getSimpleName();
        return new ClassFormatException("wrong constant type at #" + index + ": expected " + expected + ", found " + found);
    }

    Constant[] raw() {
        return entries;
    }
}

code.src/main/java/ae/classfile/Descriptor.ja:
package ae.classfile;

import java.util.ArrayList;
import java.util.List;

/** Parser for field and method descriptors (JVMS 4.3). */
public final class Descriptor {
    private static final int MAX_SLOTS = 255;
    private static final int MAX_DIMS = 255;

    private Descriptor() {
    }

    public static Type parseField(String d) {
        int[] pos = {0};
        Type t = type(d, pos, false);
        if (pos[0] != d.length()) {
            throw bad(d, "trailing characters");
        }
        return t;
    }

    public static MethodDescriptor parseMethod(String d) {
        if (d.isEmpty() || d.charAt(0) != '(') {
            throw bad(d, "must start with '('");
        }
        int[] pos = {1};
        List<Type> params = new ArrayList<>();
        int slots = 0;
        while (true) {
            if (pos[0] >= d.length()) {
                throw bad(d, "missing ')'");
            }
            if (d.charAt(pos[0]) == ')') {
                pos[0]++;
                break;
            }
            Type t = type(d, pos, false);
            slots += t.slots();
            if (slots > MAX_SLOTS) {
                throw bad(d, "more than 255 argument slots");
            }
            params.add(t);
        }
        Type ret = type(d, pos, true);
        if (pos[0] != d.length()) {
            throw bad(d, "trailing characters");
        }
        return new MethodDescriptor(List.copyOf(params), ret);
    }

    private static Type type(String d, int[] pos, boolean voidAllowed) {
        int dims = 0;
        while (pos[0] < d.length() && d.charAt(pos[0]) == '[') {
            dims++;
            pos[0]++;
            if (dims > MAX_DIMS) {
                throw bad(d, "more than 255 array dimensions");
            }
        }
        if (pos[0] >= d.length()) {
            throw bad(d, "unexpected end");
        }
        char c = d.charAt(pos[0]++);
        switch (c) {
            case 'B', 'C', 'D', 'F', 'I', 'J', 'S', 'Z':
                return new Type(c, null, dims);
            case 'V':
                if (!voidAllowed || dims > 0) {
                    throw bad(d, "void is only legal as a return type");
                }
                return new Type('V', null, 0);
            case 'L':
                int semi = d.indexOf(';', pos[0]);
                if (semi < 0) {
                    throw bad(d, "unterminated class name");
                }
                String name = d.substring(pos[0], semi);
                if (name.isEmpty() || name.indexOf('.') >= 0 || name.indexOf('[') >= 0) {
                    throw bad(d, "illegal class name");
                }
                pos[0] = semi + 1;
                return new Type('L', name, dims);
            default:
                throw bad(d, "unknown type letter '" + c + "'");
        }
    }

    private static ClassFormatException bad(String d, String why) {
        return new ClassFormatException("bad descriptor '" + d + "': " + why);
    }
}

package ae.classfile;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Strict bytecode decoder plus a javap-style operand renderer. */
public final class Disassembler {
    private static final String[] ATYPES = {"boolean", "char", "float", "double", "byte", "short", "int", "long"};

    private Disassembler() {
    }

    /** Decodes a whole code array; operand bounds, wide targets, switch layout and atype are validated. */
    public static List<Instruction> decode(byte[] code) {
        List<Instruction> out = new ArrayList<>();
        int pos = 0;
        while (pos < code.length) {
            Instruction in = decodeOne(code, pos);
            out.add(in);
            pos += in.length();
        }
        return out;
    }

    private static Instruction decodeOne(byte[] c, int pos) {
        int op = c[pos] & 0xFF;
        String name = Opcodes.name(op);
        int fixed = Opcodes.fixedLength(op);
        if (fixed > 0 && pos + fixed > c.length) {
            throw new ClassFormatException("truncated " + name + " at " + pos);
        }
        switch (Opcodes.kind(op)) {
            case NONE:
                // implicit local forms carry the slot number in the opcode itself
                if (op >= 0x1a && op <= 0x2d) {
                    return Instruction.simple(pos, op, 1, (op - 0x1a) % 4, 0);
                }
                if (op >= 0x3b && op <= 0x4e) {
                    return Instruction.simple(pos, op, 1, (op - 0x3b) % 4, 0);
                }
                return Instruction.simple(pos, op, 1, 0, 0);
            case VALUE:
                return Instruction.simple(pos, op, fixed, fixed == 2 ? c[pos + 1] : s2(c, pos + 1), 0);
            case CP:
                return Instruction.simple(pos, op, fixed, fixed == 2 ? u1(c, pos + 1) : u2(c, pos + 1), 0);
            case LOCAL:
                return Instruction.simple(pos, op, 2, u1(c, pos + 1), 0);
            case IINC:
                return Instruction.simple(pos, op, 3, u1(c, pos + 1), c[pos + 2]);
            case BRANCH: {
                int off = fixed == 3 ? s2(c, pos + 1) : s4(c, pos + 1);
                return new Instruction(pos, op, false, fixed, 0, 0, new int[] {pos + off}, new int[0]);
            }
            case NEWARRAY: {
                int t = u1(c, pos + 1);
                if (t < 4 || t > 11) {
                    throw new ClassFormatException("bad newarray type " + t + " at " + pos);
                }
                return Instruction.simple(pos, op, 2, t, 0);
            }
            case CP_COUNT: {
                int idx = u2(c, pos + 1);
                int n = u1(c, pos + 3);
                if (op == Opcodes.INVOKEINTERFACE) {
                    if (n == 0) {
                        throw new ClassFormatException("invokeinterface count must be positive at " + pos);
                    }
                    if (u1(c, pos + 4) != 0) {
                        throw new ClassFormatException("invokeinterface operand byte must be zero at " + pos);
                    }
                    return Instruction.simple(pos, op, 5, idx, n);
                }
                if (n == 0) {
                    throw new ClassFormatException("multianewarray dimensions must be positive at " + pos);
                }
                return Instruction.simple(pos, op, 4, idx, n);
            }
            case INDY:
                if (u2(c, pos + 3) != 0) {
                    throw new ClassFormatException("invokedynamic operand bytes must be zero at " + pos);
                }
                return Instruction.simple(pos, op, 5, u2(c, pos + 1), 0);
            case WIDE:
                return decodeWide(c, pos);
            case SWITCH:
                return decodeSwitch(c, pos, op);
            default:
                throw new ClassFormatException("unhandled opcode " + name);
        }
    }

    private static Instruction decodeWide(byte[] c, int pos) {
        if (pos + 1 >= c.length) {
            throw new ClassFormatException("truncated wide at " + pos);
        }
        int w = c[pos + 1] & 0xFF;
        boolean iinc = w == Opcodes.IINC;
        boolean local = (w >= 0x15 && w <= 0x19) || (w >= 0x36 && w <= 0x3a) || w == Opcodes.RET;
        if (!iinc && !local) {
            throw new ClassFormatException("wide cannot modify opcode 0x" + Integer.toHexString(w) + " at " + pos);
        }
        int length = iinc ? 6 : 4;
        if (pos + length > c.length) {
            throw new ClassFormatException("truncated wide at " + pos);
        }
        return new Instruction(pos, w, true, length, u2(c, pos + 2), iinc ? s2(c, pos + 4) : 0,
            new int[0], new int[0]);
    }

    private static Instruction decodeSwitch(byte[] c, int pos, int op) {
        int p = (pos + 4) & ~3;           // operands start at the next multiple of 4
        boolean table = op == Opcodes.TABLESWITCH;
        long header = table ? 12 : 8;
        if (p + header > c.length) {
            throw new ClassFormatException("truncated " + Opcodes.name(op) + " at " + pos);
        }
        int dflt = pos + s4(c, p);
        if (table) {
            int low = s4(c, p + 4);
            int high = s4(c, p + 8);
            if (low > high) {
                throw new ClassFormatException("tableswitch low > high at " + pos);
            }
            long count = (long) high - low + 1;
            long end = p + 12 + 4 * count;
            if (end > c.length) {
                throw new ClassFormatException("truncated tableswitch at " + pos);
            }
            int[] targets = new int[(int) count + 1];
            targets[0] = dflt;
            for (int i = 0; i < count; i++) {
                targets[i + 1] = pos + s4(c, p + 12 + 4 * i);
            }
            return new Instruction(pos, op, false, (int) end - pos, low, high, targets, new int[0]);
        }
        int npairs = s4(c, p + 4);
        if (npairs < 0) {
            throw new ClassFormatException("negative lookupswitch pair count at " + pos);
        }
        long end = p + 8 + 8L * npairs;
        if (end > c.length) {
            throw new ClassFormatException("truncated lookupswitch at " + pos);
        }
        int[] keys = new int[npairs];
        int[] targets = new int[npairs + 1];
        targets[0] = dflt;
        for (int i = 0; i < npairs; i++) {
            keys[i] = s4(c, p + 8 + 8 * i);
            if (i > 0 && keys[i] <= keys[i - 1]) {
                throw new ClassFormatException("lookupswitch keys not strictly ascending at " + pos);
            }
            targets[i + 1] = pos + s4(c, p + 12 + 8 * i);
        }
        return new Instruction(pos, op, false, (int) end - pos, 0, 0, targets, keys);
    }

    /** Every branch and switch target must be the start of a decoded instruction. */
    public static void validateTargets(List<Instruction> ins, int codeLength) {
        Set<Integer> starts = new HashSet<>();
        for (Instruction in : ins) {
            starts.add(in.offset());
        }
        for (Instruction in : ins) {
            for (int t : in.targets()) {
                if (!starts.contains(t)) {
                    throw new ClassFormatException("branch target " + t + " of " + in.mnemonic() + " at "
                        + in.offset() + " is not an instruction start (code length " + codeLength + ")");
                }
            }
        }
    }

    /** javap-style text for one instruction, without its offset. */
    public static String render(Instruction in) {
        String name = in.mnemonic();
        return switch (Opcodes.kind(in.opcode())) {
            case NONE -> name;
            case VALUE, LOCAL -> name + " " + in.operand();
            case CP -> name + " #" + in.operand();
            case IINC -> name + " " + in.operand() + ", " + in.operand2();
            case BRANCH -> name + " " + in.targets()[0];
            case NEWARRAY -> name + " " + ATYPES[in.operand() - 4];
            case CP_COUNT -> name + " #" + in.operand() + ", " + in.operand2();
            case INDY -> name + " #" + in.operand() + ", 0";
            case WIDE -> throw new IllegalStateException("wide is folded into its operand instruction");
            case SWITCH -> renderSwitch(in, name);
        };
    }

    private static String renderSwitch(Instruction in, String name) {
        List<String> parts = new ArrayList<>();
        for (int i = 1; i < in.targets().length; i++) {
            long key = in.opcode() == Opcodes.TABLESWITCH ? (long) in.operand() + (i - 1) : in.keys()[i - 1];
            parts.add(key + ": " + in.targets()[i]);
        }
        parts.add("default: " + in.targets()[0]);
        return name + " {" + String.join(", ", parts) + "}";
    }

    private static int u1(byte[] c, int i) {
        return c[i] & 0xFF;
    }

    private static int u2(byte[] c, int i) {
        return ((c[i] & 0xFF) << 8) | (c[i + 1] & 0xFF);
    }

    private static int s2(byte[] c, int i) {
        return (short) u2(c, i);
    }

    private static int s4(byte[] c, int i) {
        return (u2(c, i) << 16) | u2(c, i + 2);
    }
}

